package com.nextrade.api.security;
import org.springframework.lang.NonNull; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.security.core.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.*;
public final class JwtAuthenticationFilter extends OncePerRequestFilter {private final AccessTokenService tokens;public JwtAuthenticationFilter(AccessTokenService tokens){this.tokens=tokens;}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{var j=tokens.parse(h.substring(7));var c=j.getPayload();if("access".equals(c.get("token_type",String.class))){String role=c.get("role",String.class);var auth=new UsernamePasswordAuthenticationToken(c.getSubject(),null,java.util.List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_"+role)));SecurityContextHolder.getContext().setAuthentication(auth);}}catch(RuntimeException ignored){}}try{chain.doFilter(req,res);}finally{SecurityContextHolder.clearContext();}}
}
